def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        raise ValueError("numbers list must not be empty")
    try:
        mean = sum(numbers) / len(numbers)
    except TypeError as e:
        raise TypeError("All elements must be numeric") from e
    mad = sum(abs(x - mean) for x in numbers) / len(numbers)
    return mad

def add(a: int, b: int) -> int:
    """Adds two integer numbers together."""
    if not isinstance(a, int) or not isinstance(b, int):
        raise TypeError("Both arguments must be integers.")
    try:
        return a + b
    except Exception as e:
        raise RuntimeError(f"Failed to add numbers: {e}") from e

def max_value_on_paths(N: int, grid_values: list) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each cell value can be collected at most once, even if both paths pass through it.
    """
    if N <= 0:
        return 0

    # Initialize grid with zeros (1-indexed)
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # Edge case: single cell grid
    if N == 1:
        return grid[1][1]

    # DP arrays: dp_prev and dp_cur are (N+1)x(N+1) with -inf initialization
    NEG_INF = -10**15
    dp_prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]

    # Iterate over steps t = x1 + y1 = x2 + y2 from 3 to 2N
    for t in range(3, 2 * N + 1):
        dp_cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        # x1 ranges from max(1, t-N) to min(N, t-1)
        x1_min = max(1, t - N)
        x1_max = min(N, t - 1)
        for x1 in range(x1_min, x1_max + 1):
            y1 = t - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(x1_min, x1_max + 1):
                y2 = t - x2
                if y2 < 1 or y2 > N:
                    continue
                best = NEG_INF
                # Consider all combinations of previous moves
                for prev_x1 in (x1 - 1, x1):
                    if prev_x1 < 1:
                        continue
                    for prev_x2 in (x2 - 1, x2):
                        if prev_x2 < 1:
                            continue
                        val = dp_prev[prev_x1][prev_x2]
                        if val > best:
                            best = val
                if best == NEG_INF:
                    continue
                add = grid[x1][y1]
                if x1 != x2 or y1 != y2:
                    add += grid[x2][y2]
                dp_cur[x1][x2] = best + add
        dp_prev = dp_cur

    result = dp_prev[N][N]
    return result if result != NEG_INF else 0

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0:
        raise ValueError("n must be positive")
    if m < 0:
        raise ValueError("m must be non-negative")
    dp = [0]*n
    dp[0] = 1
    for step in range(m):
        new = [0]*n
        for i in range(n):
            left = (i-1)%n
            right = (i+1)%n
            new[i] = dp[left] + dp[right]
        dp = new
    return dp[0]

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic type and length checks
    if not isinstance(encoded, str) or not isinstance(original, str) or not isinstance(message, str):
        return "Failed"
    if len(encoded) != len(original):
        return "Failed"
    if len(encoded) == 0:
        return "Failed"

    mapping = {}
    reverse_mapping = {}
    for e_char, o_char in zip(encoded, original):
        # Check for consistent mapping
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"
        else:
            mapping[e_char] = o_char
        # Check for bijection
        if o_char in reverse_mapping:
            if reverse_mapping[o_char] != e_char:
                return "Failed"
        else:
            reverse_mapping[o_char] = e_char

    # Ensure all 26 uppercase letters are represented in the mapping
    import string
    alphabet = set(string.ascii_uppercase)
    if set(mapping.keys()) != alphabet or set(mapping.values()) != alphabet:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps. Returns the minimum number of steps or "NO ANSWER!".
    """
    # Input validation
    if not isinstance(A, str) or not isinstance(B, str):
        raise TypeError("A and B must be strings")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    for rule in rules:
        if not (isinstance(rule, tuple) and len(rule) == 2 and
                isinstance(rule[0], str) and isinstance(rule[1], str)):
            raise TypeError("Each rule must be a tuple of two strings")

    # Quick check
    if A == B:
        return 0

    max_depth = 10
    visited = {A}
    queue = [(A, 0)]

    while queue:
        current, depth = queue.pop(0)
        if depth >= max_depth:
            continue
        next_depth = depth + 1
        for src, tgt in rules:
            if src == "":
                continue  # skip empty source to avoid infinite loops
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return next_depth
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, next_depth))
                start = idx + 1  # allow overlapping matches
    return "NO ANSWER!"

def max_herb_value(T: int, M: int, herbs: list) -> int:
    """
    Calculate the maximum total value of herbs that can be picked within a given time limit.

    This function solves a variation of the 0/1 knapsack problem where the goal is to maximize
    the total value of herbs picked without exceeding the time limit. Each herb can be picked
    at most once and has an associated time cost and value.

    Args:
    - T (int): The total time available for picking herbs.
    - M (int): The number of different herbs in the cave.
    - herbs (List[Tuple[int, int]]): A list of tuples, where each tuple contains two integers
      representing the time required to pick the herb and the herb's value, respectively.

    Returns:
    - int: The maximum total value of herbs that can be picked within the time limit.
    """
    # Basic validation
    if T is None or M is None or herbs is None:
        raise ValueError("Input arguments cannot be None.")
    if not isinstance(T, int) or not isinstance(M, int):
        raise TypeError("T and M must be integers.")
    if T < 0 or M < 0:
        raise ValueError("T and M must be non-negative.")
    if not isinstance(herbs, list):
        raise TypeError("herbs must be a list of tuples.")
    # If no herbs or no time, result is 0
    if T == 0 or M == 0 or len(herbs) == 0:
        return 0

    # Use the actual number of herbs provided
    n = len(herbs)

    # Initialize DP array
    dp = [0] * (T + 1)

    for idx in range(n):
        try:
            time_cost, value = herbs[idx]
        except Exception:
            # Skip malformed entries
            continue
        if not isinstance(time_cost, int) or not isinstance(value, int):
            continue
        if time_cost < 0 or value < 0:
            continue
        if time_cost > T:
            # Cannot pick this herb due to time constraint
            continue
        # 0/1 knapsack update (reverse iteration)
        for t in range(T, time_cost - 1, -1):
            new_val = dp[t - time_cost] + value
            if new_val > dp[t]:
                dp[t] = new_val

    return max(dp)

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    """
    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.

    This function uses a dynamic programming approach to determine the maximum volume that can be occupied
    in the box by any subset of the given items. It then returns the difference between the box's total capacity
    and this maximum occupied volume, which is the minimum remaining space.

    Args:
    - V (int): The total capacity of the box.
    - n (int): The number of items to consider for packing into the box.
    - volumes (List[int]): A list of the volumes of the n items.

    Returns:
    - int: The minimum remaining space in the box after fitting the items.
    """
    # Input validation
    if not isinstance(V, int) or not isinstance(n, int):
        raise TypeError("V and n must be integers")
    if V < 0:
        raise ValueError("Box capacity V must be non-negative")
    if n < 0:
        raise ValueError("Number of items n must be non-negative")
    if not isinstance(volumes, list):
        raise TypeError("volumes must be a list")
    if len(volumes) != n:
        raise ValueError("Length of volumes list must equal n")
    for idx, vol in enumerate(volumes):
        if not isinstance(vol, int):
            raise TypeError(f"Volume at index {idx} is not an integer")
        if vol < 0:
            raise ValueError(f"Volume at index {idx} is negative")

    # Edge cases
    if V == 0:
        return 0
    if n == 0:
        return V

    # Dynamic programming: 0/1 knapsack to find maximum achievable sum <= V
    dp = [False] * (V + 1)
    dp[0] = True
    for vol in volumes:
        if vol > V:
            continue
        for cap in range(V, vol - 1, -1):
            if dp[cap - vol]:
                dp[cap] = True

    # Find the largest achievable sum
    max_sum = 0
    for cap in range(V, -1, -1):
        if dp[cap]:
            max_sum = cap
            break

    return V - max_sum
